import{buildProductionChecklist,checklistView,reviewedChecklist,checklistCSV}from './production-checklist-core.js?v=20261027motion';
import{mediaTaskLabel}from './media-task.js?v=20261027motion';
const $=id=>document.getElementById(id);let data=null,review=new Map(),page=0,onSeek=()=>{};
function download(content,type,name){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function draw(){
 const box=$('production-tasks');box.replaceChildren();const disabled=!data;for(const id of ['production-csv','production-json','production-category','production-filter'])$(id).disabled=disabled;
 if(!data){$('production-summary').textContent='导入参考视频完成分镜后，自动生成按时间排序的制作任务。';$('production-rhythm').textContent='尚无候选镜头节奏数据。';$('production-pagination').textContent='';return}
 const view=checklistView(data,review,$('production-category').value,$('production-filter').value,page);page=view.page;$('production-summary').textContent=`${view.done}/${data.tasks.length} 项已人工核对 · 当前筛选 ${view.total} 项。勾选不代表系统已验证制作效果。`;
 const r=data.rhythm;$('production-rhythm').textContent=`候选镜头 ${r.shots} 段 · 中位时长 ${r.median} 秒 · 最短 ${r.shortest} 秒 · 最长 ${r.longest} 秒 · 每分钟约 ${r.cutsPerMinute} 个候选切点。仅描述节奏，不据此评判创意质量。`;
 for(const task of view.tasks){const card=document.createElement('article');card.className='production-task';const head=document.createElement('div');head.className='row';const label=document.createElement('label');label.className='production-check';const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=!!review.get(task.id)?.checked;const title=document.createElement('strong');title.textContent=`${task.start.toFixed(2)}–${task.end.toFixed(2)} 秒 · ${task.category} · ${task.title}`;label.append(checkbox,title);head.append(label);const play=document.createElement('button');play.className='secondary';play.textContent='定位原片';play.onclick=()=>{if(mediaTaskLabel()){$('production-status').textContent='当前正在'+mediaTaskLabel()+'，结束或停止后可播放核对；现在可以阅读和填写清单。';return}onSeek(task.start)};head.append(play);card.append(head);
 const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='展开操作步骤与依据';details.open=false;details.append(summary);for(const value of [task.parameters,task.reason]){const p=document.createElement('p');p.textContent=value;details.append(p)}const list=document.createElement('ol');task.steps.forEach(step=>{const li=document.createElement('li');li.textContent=step;list.append(li)});details.append(list);card.append(details);
 const note=document.createElement('label');note.textContent='我的制作备注';const input=document.createElement('textarea');input.maxLength=1000;input.rows=2;input.placeholder='例如：白闪缩短到 2 帧，音效对齐抬手动作';input.value=review.get(task.id)?.note||'';input.oninput=()=>{review.set(task.id,{checked:checkbox.checked,note:input.value});$('production-status').textContent='备注保存在当前页面，可导出备份；刷新会清除。'};note.append(input);card.append(note);checkbox.onchange=()=>{review.set(task.id,{checked:checkbox.checked,note:input.value});$('production-status').textContent='已更新人工核对状态。';if($('production-filter').value==='all'){$('production-summary').textContent=`${data.tasks.filter(t=>review.get(t.id)?.checked).length}/${data.tasks.length} 项已人工核对 · 当前筛选 ${view.total} 项。勾选不代表系统已验证制作效果。`}else{draw();$('production-filter').focus()}};box.append(card)}
 if(!view.total){const p=document.createElement('p');p.textContent='当前筛选没有任务。可以切换类别或核对状态。';box.append(p)}const prev=document.createElement('button'),next=document.createElement('button'),count=document.createElement('span');prev.className=next.className='secondary';prev.textContent='上一页任务';next.textContent='下一页任务';prev.disabled=page===0;next.disabled=page>=view.pages-1;count.textContent=`第 ${page+1}/${view.pages} 页 · 每页 10 项`;prev.onclick=()=>{page--;draw()};next.onclick=()=>{page++;draw()};$('production-pagination').replaceChildren(prev,count,next);
 $('production-unknown').textContent=data.unknown.length?'仍待核对的类别：'+data.unknown.map(r=>r.category+'（'+r.status+'）').join('、')+'。无候选不代表没有效果。':'各类均有线索，仍需逐项人工核对。';
}
export function updateProductionChecklist(reference,shots,rows,seek,audio=null){try{data=buildProductionChecklist(reference,shots,rows,audio);onSeek=seek;const valid=new Set(data.tasks.map(t=>t.id));for(const id of review.keys())if(!valid.has(id))review.delete(id);const select=$('production-category'),old=select.value;select.replaceChildren(new Option('全部类别','all'));for(const name of new Set(data.tasks.map(t=>t.category)))select.add(new Option(name,name));select.value=[...select.options].some(o=>o.value===old)?old:'all';draw()}catch(e){$('production-status').textContent='清单未生成：'+e.message}}
for(const id of ['production-category','production-filter'])$(id).onchange=()=>{page=0;draw()};
$('production-csv').onclick=()=>{if(data)download(checklistCSV(data,review),'text/csv;charset=utf-8','ClipPilot-剪辑制作清单.csv')};
$('production-json').onclick=()=>{if(data)download(JSON.stringify(reviewedChecklist(data,review),null,2),'application/json','ClipPilot-Agent制作任务.json')};
$('production-open').onclick=()=>{const panel=$('production-panel');panel.open=true;panel.scrollIntoView({behavior:'smooth',block:'start'});panel.focus({preventScroll:true})};
document.addEventListener('reference-changed',()=>{data=null;review.clear();page=0;$('production-filter').value='all';$('production-category').replaceChildren(new Option('全部类别','all'));draw();$('production-unknown').textContent='';$('production-status').textContent='已更换视频，清单与核对状态已清空。'});draw();
